/**
 * Stage-1 duplicate-prune awareness for the Plan-B dataset generators.
 *
 * Stage 1 removed 18 duplicate product listings from the site; when two listings
 * were the same physical product the page that lost kept no URL of its own and
 * instead 301s to the survivor (see public/_redirects, generated by prerender).
 *
 * The four asset datasets were generated BEFORE that decision, so they still
 * carry the losing rows. A comparison table that lists one bike twice — once
 * under a URL that only resolves through a redirect, once under the real one —
 * is wrong twice over: the row count is inflated, every "N of M publish X"
 * sentence on those pages counts the duplicate, and one row links out through a
 * 301.
 *
 * Filter BEFORE any per-category selection so the survivor is always available
 * to absorb its duplicate, even when the two live in different categories.
 *
 * Reads src/data/prunedProducts.generated.ts by regex: a plain .mjs cannot
 * import a .ts module, and duplicating the map here is how the two drift apart.
 * (Same reason scripts/check-review-counts.mjs reads its ceiling this way.)
 */
import { readFileSync } from "node:fs";
import { resolve } from "node:path";

const GENERATED_RELATIVE = "src/data/prunedProducts.generated.ts";

/**
 * duplicateId -> survivorId, lower-cased. Every id the site no longer publishes
 * maps to the listing that absorbed it.
 */
export function loadPrunedMap(root = process.cwd()) {
  const text = readFileSync(resolve(root, GENERATED_RELATIVE), "utf8");
  const block = /"duplicateOf"\s*:\s*\{([\s\S]*?)\n {2}\}/.exec(text);
  if (!block) {
    throw new Error(`No duplicateOf map found in ${GENERATED_RELATIVE} — pruning metadata missing.`);
  }
  const map = new Map();
  for (const [, duplicateId, survivorId] of block[1].matchAll(/"([^"]+)"\s*:\s*"([^"]+)"/g)) {
    map.set(duplicateId.trim().toLowerCase(), survivorId.trim().toLowerCase());
  }
  if (map.size === 0) throw new Error(`duplicateOf map in ${GENERATED_RELATIVE} is empty.`);
  return map;
}

/**
 * Products the site actually publishes: every Stage-1 loser whose survivor is
 * still present is dropped. A loser whose survivor is NOT in this list is kept —
 * dropping it would delete the product's only remaining record.
 */
export function dropPrunedDuplicates(products, pruneMap) {
  const present = new Set(products.map((p) => String(p?.id ?? "").trim().toLowerCase()));
  const dropped = [];
  const kept = products.filter((product) => {
    const id = String(product?.id ?? "").trim().toLowerCase();
    const survivor = pruneMap.get(id);
    if (!survivor) return true;
    if (!present.has(survivor)) return true;
    dropped.push(`${id} -> ${survivor}`);
    return false;
  });
  return { products: kept, dropped };
}

/**
 * Wire this into each generator right after the export is read:
 *   const allProducts = raw?.data?.collections?.products || [];
 *   const { products } = dropPrunedDuplicates(allProducts, loadPrunedMap());
 */
export function publishedProducts(allProducts, root = process.cwd()) {
  return dropPrunedDuplicates(allProducts, loadPrunedMap(root));
}
